/**
 * Catalog search configuration (ADR 0034 decision 9). With `SEARCH_ENABLED=false` (the default) no `MEILI_*` variable is
 * read at all: no client, no connection, no routes. The patterns equal `SEARCH_INDEX_PREFIX_PATTERN` of `@fluxkit/core`
 * (a test in apps/api asserts it); this package does not depend on core, so they are repeated here.
 */
export const DEFAULT_MEILI_INDEX_PREFIX = "fluxkit_";
export const MEILI_INDEX_PREFIX_PATTERN = /^[a-z][a-z0-9_]{0,31}_$/;
/** Printable ASCII without space: what a key generated by the engine (or any sane secret) looks like. */
const MEILI_API_KEY_PATTERN = /^[\x21-\x7e]{16,256}$/;

export type SearchEnv =
  | { readonly enabled: false }
  | {
      readonly enabled: true;
      /** Engine base URL without a trailing slash. Never sent to a browser. */
      readonly meiliUrl: string;
      /** The scoped key (README "Search"); never logged. */
      readonly meiliApiKey: string;
      /** Prefix of every index uid this deployment owns. */
      readonly indexPrefix: string;
    };

/** A problem with `MEILI_URL`, as fixed text (the value may carry credentials and must not reach a log). */
export function describeMeiliUrlProblem(value: string): string | undefined {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return "must be an absolute http or https URL";
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    return "must be an absolute http or https URL";
  }
  if (url.username !== "" || url.password !== "" || /^[a-z]+:\/\/[^/]*@/i.test(value)) {
    return "must not contain credentials";
  }
  if (value.includes("?") || value.includes("#")) {
    return "must not contain a query or a fragment";
  }
  return undefined;
}

/** The URL without a trailing slash, so paths can be appended. */
export function normalizeMeiliUrl(value: string): string {
  return value.replace(/\/+$/, "");
}

function isPrivateIPv4(address: string): boolean {
  const [a = -1, b = -1] = address.split(".").map(Number);
  return a === 10 || a === 127 || (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168);
}

function isPrivateIPv6(address: string): boolean {
  const lower = address.toLowerCase();
  return lower === "::1" || /^f[cd][0-9a-f]{2}:/.test(lower);
}

/**
 * True for a host on a private network: loopback, RFC 1918 IPv4, IPv6 loopback or unique local, `localhost`, or a single
 * label (a container service name such as `meilisearch`). A public host name or address is not private.
 */
export function isPrivateMeiliHost(hostname: string): boolean {
  // WHATWG URL parsing has already normalized the host: IPv6 in brackets, IPv4 as four decimal parts.
  if (hostname.startsWith("[")) {
    return isPrivateIPv6(hostname.slice(1, -1));
  }
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(hostname)) {
    return isPrivateIPv4(hostname);
  }
  return hostname === "localhost" || !hostname.includes(".");
}

export function isValidMeiliApiKey(value: string): boolean {
  return MEILI_API_KEY_PATTERN.test(value);
}
